    17→use anyhow::{Context, Result};
    18→use clap::Args;
    19→use std::path::PathBuf;
    20→
    21→use crate::cluster::{paths::expand_tilde, process, state::*};
    22→use crate::output;
    23→
    24→#[derive(Args)]
    25→pub struct StopArgs {
    26→    /// Working directory
    27→    #[arg(long, default_value = "~/.spice/distributed")]
    28→    work_dir: PathBuf,
    29→
    30→    /// Force kill processes if graceful shutdown fails
    31→    #[arg(long)]
    32→    force: bool,
    33→
    34→    /// Timeout for graceful shutdown (seconds)
    35→    #[arg(long, default_value = "10")]
    36→    timeout: u64,
    37→}
    38→
    39→pub async fn execute(args: StopArgs) -> Result<()> {
    40→    // Expand tilde in paths
    41→    let work_dir = expand_tilde(&args.work_dir);
    42→
    43→    // Check if cluster is running
    44→    if !state_exists(&work_dir) {
    45→        output::error("No cluster is currently running.");
    46→        return Err(anyhow::anyhow!("Cluster not running"));
    47→    }
    48→
    49→    // Load state
    50→    let state = load_state(&work_dir).context("Failed to load cluster state")?;
    51→
    52→    output::info("Stopping distributed Spice cluster...");
    53→
    54→    // Stop executors first (sequentially)
    55→    let mut executor_errors = Vec::new();
    56→    for executor in &state.executors {
    57→        output::info(&format!("Stopping {}...", executor.name));
    58→        let result = if args.force {
    59→            process::kill_process(executor.pid)
    60→        } else {
    61→            process::stop_process(executor.pid, args.timeout)
    62→        };
    63→
    64→        match result {
    65→            Ok(()) => output::success(&format!("{} stopped", executor.name)),
    66→            Err(e) => {
    67→                output::warning(&format!("Failed to stop {}: {e}", executor.name));
    68→                executor_errors.push((executor.name.clone(), e));
    69→            }
    70→        }
    71→    }
    72→
    73→    // Stop scheduler
    74→    output::info("Stopping scheduler...");
    75→    let scheduler_result = if args.force {
    76→        process::kill_process(state.scheduler.pid)
    77→    } else {
    78→        process::stop_process(state.scheduler.pid, args.timeout)
    79→    };
    80→
    81→    let scheduler_failed = scheduler_result.is_err();
    82→    match scheduler_result {
    83→        Ok(()) => output::success("Scheduler stopped"),
    84→        Err(e) => {
    85→            output::warning(&format!("Failed to stop scheduler: {e}"));
    86→        }
    87→    }
    88→
    89→    // Report results and remove state file only if all components stopped successfully
    90→    let has_errors = !executor_errors.is_empty() || scheduler_failed;
    91→    if !has_errors {
    92→        remove_state(&work_dir).context("Failed to remove cluster state")?;
    93→        output::success("Cluster stopped successfully!");
    94→        Ok(())
    95→    } else {
    96→        output::warning("Cluster stopped with some errors. Check the output above for details.");
    97→        output::info(
    98→            "State file retained for inspection; use 'distributed stop --force' to force cleanup.",
    99→        );
   100→        Err(anyhow::anyhow!(
   101→            "Failed to stop all cluster processes; some components may still be running"
   102→        ))
   103→    }
   104→}
