   149→/// Check if a process is alive using sysinfo.
   150→#[cfg(unix)]
   151→pub fn is_process_alive(pid: u32) -> bool {
   152→    let mut system = System::new();
   153→    system.refresh_processes_specifics(
   154→        sysinfo::ProcessesToUpdate::Some(&[sysinfo::Pid::from_u32(pid)]),
   155→        true,
   156→        ProcessRefreshKind::everything(),
   157→    );
   158→    system.process(sysinfo::Pid::from_u32(pid)).is_some()
