   166→/// Stop a process gracefully with SIGTERM, falling back to SIGKILL if timeout exceeded.
   167→/// Note: This function uses blocking operations and should be called from spawn_blocking context
   168→/// when used in async code.
   169→#[cfg(unix)]
   170→pub fn stop_process(pid: u32, timeout_secs: u64) -> Result<()> {
   171→    let pid = Pid::from_raw(pid as i32);
   172→
   173→    // Check if process is alive
   174→    if !is_process_alive(pid.as_raw() as u32) {
   175→        return Ok(());
   176→    }
   177→
   178→    // Send SIGTERM
   179→    signal::kill(pid, Signal::SIGTERM).context("Failed to send SIGTERM")?;
   180→
   181→    // Wait for process to terminate
   182→    let start = std::time::Instant::now();
   183→    while start.elapsed() < Duration::from_secs(timeout_secs) {
   184→        if !is_process_alive(pid.as_raw() as u32) {
   185→            return Ok(());
   186→        }
   187→        std::thread::sleep(Duration::from_millis(100));
   188→    }
   189→
   190→    // Process didn't terminate, send SIGKILL
   191→    signal::kill(pid, Signal::SIGKILL).context("Failed to send SIGKILL")?;
   192→
   193→    // Wait a bit more for SIGKILL to take effect
   194→    std::thread::sleep(Duration::from_secs(1));
   195→
   196→    if is_process_alive(pid.as_raw() as u32) {
   197→        return Err(anyhow!("Failed to kill process {pid}"));
   198→    }
   199→
   200→    Ok(())
   201→}
   202→
   203→#[cfg(not(unix))]
   204→pub fn stop_process(_pid: u32, _timeout_secs: u64) -> Result<()> {
   205→    Err(anyhow!(
   206→        "Process control is not supported on non-Unix platforms"
   207→    ))
   208→}
