   237→/// Read the last N lines from a log file.
   238→/// Uses efficient bounded reading when possible to avoid loading large files into memory.
   239→pub fn read_log_tail(log_file: &Path, lines: usize) -> Result<String> {
   240→    use std::io::{BufRead, BufReader};
   241→
   242→    let file = fs::File::open(log_file).context("Failed to open log file")?;
   243→    let reader = BufReader::new(file);
   244→
   245→    // Collect last N lines efficiently
   246→    let mut tail_lines: Vec<String> = Vec::with_capacity(lines);
   247→    for line in reader.lines() {
   248→        let line = line.context("Failed to read line from log file")?;
   249→        tail_lines.push(line);
   250→        if tail_lines.len() > lines {
   251→            tail_lines.remove(0);
   252→        }
   253→    }
   254→
   255→    Ok(tail_lines.join("\n"))
   256→}
