   179→    signal::kill(pid, Signal::SIGTERM).context("Failed to send SIGTERM")?;
   180→
   181→    // Wait for process to terminate
   182→    let start = std::time::Instant::now();
   183→    while start.elapsed() < Duration::from_secs(timeout_secs) {
   184→        if !is_process_alive(pid.as_raw() as u32) {
   185→            return Ok(());
   186→        }
   187→        std::thread::sleep(Duration::from_millis(100));
   188→    }
   189→
   190→    // Process didn't terminate, send SIGKILL
   191→    signal::kill(pid, Signal::SIGKILL).context("Failed to send SIGKILL")?;
   192→
   193→    // Wait a bit more for SIGKILL to take effect
   194→    std::thread::sleep(Duration::from_secs(1));
   195→
   196→    if is_process_alive(pid.as_raw() as u32) {
   197→        return Err(anyhow!("Failed to kill process {pid}"));
   198→    }
   199→
   200→    Ok(())
   201→}
