    17→use anyhow::{Context, Result};
    18→use clap::Args;
    19→use std::fs;
    20→use std::path::PathBuf;
    21→use std::time::Duration;
    22→
    23→use crate::cluster::{paths::expand_tilde, process, state::*};
    24→use crate::output;
    25→
    26→#[derive(Args)]
    27→pub struct LogsArgs {
    28→    /// Component to show logs for (scheduler, executor1, executor2, etc.)
    29→    component: String,
    30→
    31→    /// Log directory
    32→    #[arg(long, default_value = "~/.spice/distributed/logs")]
    33→    log_dir: PathBuf,
    34→
    35→    /// Working directory (for state file)
    36→    #[arg(long, default_value = "~/.spice/distributed")]
    37→    work_dir: PathBuf,
    38→
    39→    /// Follow log output (tail -f style)
    40→    #[arg(short, long)]
    41→    follow: bool,
    42→
    43→    /// Number of lines to show from end
    44→    #[arg(short = 'n', default_value = "50")]
    45→    tail: usize,
    46→}
    47→
    48→pub async fn execute(args: LogsArgs) -> Result<()> {
    49→    // Expand tilde in paths
    50→    let work_dir = expand_tilde(&args.work_dir);
    51→    let log_dir = expand_tilde(&args.log_dir);
    52→
    53→    // Check if cluster is running
    54→    if !state_exists(&work_dir) {
    55→        output::error("No cluster is currently running.");
    56→        output::info("Note: You can still view logs from the log directory if they exist.");
    57→
    58→        // Try to show logs from log directory anyway
    59→        let log_file = log_dir.join(format!("{}.log", args.component));
    60→        if !log_file.exists() {
    61→            output::error(&format!("Log file not found: {}", log_file.display()));
    62→            return Err(anyhow::anyhow!("Log file not found"));
    63→        }
    64→
    65→        return show_logs_from_file(&log_file, args.follow, args.tail);
    66→    }
    67→
    68→    // Load state
    69→    let state = load_state(&work_dir).context("Failed to load cluster state")?;
    70→
    71→    // Get log file path from state
    72→    let log_file = match state.get_log_path(&args.component) {
    73→        Some(path) => path.clone(),
    74→        None => {
    75→            output::error(&format!("Component '{}' not found.", args.component));
    76→            output::info("Available components:");
    77→            for component in state.list_components() {
    78→                println!("  - {component}");
    79→            }
    80→            return Err(anyhow::anyhow!("Component not found"));
    81→        }
    82→    };
    83→
    84→    // Check if log file exists
    85→    if !log_file.exists() {
    86→        output::error(&format!("Log file not found: {}", log_file.display()));
    87→        output::info(&format!(
    88→            "The component '{}' may not have started successfully.",
    89→            args.component
    90→        ));
    91→        return Err(anyhow::anyhow!("Log file not found"));
    92→    }
    93→
    94→    show_logs_from_file(&log_file, args.follow, args.tail)
    95→}
    96→
    97→fn show_logs_from_file(log_file: &PathBuf, follow: bool, tail_lines: usize) -> Result<()> {
    98→    if follow {
    99→        // Follow mode: print initial tail, then poll for new content
   100→        follow_log_file(log_file, tail_lines)
   101→    } else {
   102→        // Read last N lines
   103→        let tail =
   104→            process::read_log_tail(log_file, tail_lines).context("Failed to read log file")?;
   105→        println!("{tail}");
   106→        Ok(())
   107→    }
   108→}
   109→
   110→fn follow_log_file(log_file: &PathBuf, initial_lines: usize) -> Result<()> {
   111→    // Print initial tail
   112→    let tail =
   113→        process::read_log_tail(log_file, initial_lines).context("Failed to read log file")?;
   114→    println!("{tail}");
   115→
   116→    // Follow for new content
   117→    let mut last_size = fs::metadata(log_file)
   118→        .context("Failed to get log file metadata")?
   119→        .len();
   120→
   121→    println!("\n--- Following (Ctrl+C to stop) ---\n");
   122→
   123→    loop {
   124→        std::thread::sleep(Duration::from_millis(500));
   125→
   126→        let current_size = match fs::metadata(log_file) {
   127→            Ok(metadata) => metadata.len(),
   128→            Err(_) => {
   129→                // File was deleted, stop following
   130→                break;
   131→            }
   132→        };
   133→
   134→        if current_size > last_size {
   135→            // File grew, read new content
   136→            match fs::read_to_string(log_file).context("Failed to read log file") {
   137→                Ok(contents) => {
   138→                    let lines: Vec<&str> = contents.lines().collect();
   139→                    // Find where we left off based on approximate line count
   140→                    if !lines.is_empty() {
   141→                        // Estimate position based on file size ratio
   142→                        let estimated_start =
   143→                            (lines.len() as u64 * last_size / current_size).max(0) as usize;
   144→                        for line in lines.iter().skip(estimated_start) {
   145→                            println!("{line}");
   146→                        }
   147→                    }
   148→                }
   149→                Err(e) => {
   150→                    output::warning(&format!("Error reading updated log: {e}"));
   151→                }
   152→            }
   153→            last_size = current_size;
   154→        }
   155→    }
   156→
   157→    Ok(())
   158→}
