    35→#[derive(Serialize, Deserialize, Debug, Clone)]
    36→pub struct NodeState {
    37→    pub name: String,
    38→    pub pid: u32,
    39→    pub http_port: u16,
    40→    pub flight_port: Option<u16>, // Only for scheduler
    41→    pub node_port: u16,
    42→    pub work_dir: PathBuf,
    43→    pub log_file: PathBuf,
    44→}
    45→
    46→impl ClusterState {
    47→    /// Create a new cluster state.
    48→    #[must_use]
    49→    pub fn new(project_dir: PathBuf, scheduler: NodeState, executors: Vec<NodeState>) -> Self {
    50→        Self {
    51→            version: STATE_VERSION.to_string(),
    52→            started_at: Utc::now(),
    53→            project_dir,
    54→            scheduler,
    55→            executors,
    56→        }
    57→    }
    58→
    59→    /// Get the log file path for a given component name.
    60→    #[must_use]
    61→    pub fn get_log_path(&self, component: &str) -> Option<&PathBuf> {
    62→        if component == "scheduler" {
    63→            return Some(&self.scheduler.log_file);
    64→        }
    65→        self.executors
    66→            .iter()
    67→            .find(|e| e.name == component)
    68→            .map(|e| &e.log_file)
    69→    }
    70→
    71→    /// List all component names in the cluster.
    72→    #[must_use]
    73→    pub fn list_components(&self) -> Vec<String> {
    74→        let mut components = vec!["scheduler".to_string()];
    75→        components.extend(self.executors.iter().map(|e| e.name.clone()));
    76→        components
    77→    }
    78→
    79→    /// Get all nodes (scheduler + executors).
    80→    pub fn all_nodes(&self) -> Vec<&NodeState> {
    81→        let mut nodes = vec![&self.scheduler];
    82→        nodes.extend(&self.executors);
    83→        nodes
    84→    }
    85→}
    86→
    87→/// Check if a cluster state file exists.
    88→#[must_use]
    89→pub fn state_exists(work_dir: &Path) -> bool {
    90→    work_dir.join(STATE_FILE_NAME).exists()
    91→}
    92→
    93→/// Load cluster state from file.
    94→pub fn load_state(work_dir: &Path) -> Result<ClusterState> {
    95→    let state_path = work_dir.join(STATE_FILE_NAME);
    96→    let contents = fs::read_to_string(&state_path).context("Failed to read cluster state file")?;
    97→    serde_json::from_str(&contents).context("Failed to parse cluster state file")
    98→}
    99→
   100→/// Save cluster state to file.
   101→pub fn save_state(state: &ClusterState, work_dir: &Path) -> Result<()> {
   102→    fs::create_dir_all(work_dir).context("Failed to create working directory")?;
   103→    let state_path = work_dir.join(STATE_FILE_NAME);
   104→    let contents = serde_json::to_string_pretty(state).context("Failed to serialize state")?;
   105→    fs::write(&state_path, contents).context("Failed to write cluster state file")?;
   106→    Ok(())
   107→}
   108→
   109→/// Remove cluster state file.
   110→pub fn remove_state(work_dir: &Path) -> Result<()> {
   111→    let state_path = work_dir.join(STATE_FILE_NAME);
   112→    if state_path.exists() {
   113→        fs::remove_file(&state_path).context("Failed to remove cluster state file")?;
   114→    }
   115→    Ok(())
   116→}
