    19→/// Expand tilde in path to home directory.
    20→///
    21→/// Handles:
    22→/// - `~/path/to/file` → `/home/user/path/to/file`
    23→/// - `~` → `/home/user`
    24→/// - `~user/path` → not supported, returned as-is
    25→pub fn expand_tilde(path: &PathBuf) -> PathBuf {
    26→    let path_str = match path.to_str() {
    27→        Some(s) => s,
    28→        None => return path.clone(),
    29→    };
    30→
    31→    // Handle bare "~" as the home directory.
    32→    if path_str == "~" {
    33→        if let Some(home) = dirs::home_dir() {
    34→            return home;
    35→        }
    36→        return path.clone();
    37→    }
    38→
    39→    // Handle paths starting with "~/...".
    40→    if let Some(stripped) = path_str.strip_prefix("~/") {
    41→        if let Some(home) = dirs::home_dir() {
    42→            return home.join(stripped);
    43→        }
    44→    }
    45→
    46→    path.clone()
    47→}
