                for line in lines.iter().skip(estimated_start) {
                    println!("{line}");
                }
            }
        }
```

**Issues:**
1. **Incorrect algorithm**: File size ratio doesn't map to line count. UTF-8 variable width + line delimiters cause mismatch
2. **Off-by-one potential**: Assumes uniform character distribution; will skip/repeat lines
3. **No tracking of last line position**: If log rotates (file deleted/recreated), no recovery
4. **Inefficient**: Reads entire file every 500ms instead of seeking to last position
5. **Missing edge case**: If file shrinks (rotation), `current_size > last_size` is false, but file content is new

**Fix:** Track byte offset or line count, not size-based estimation:
```rust
let mut last_offset: u64 = 0;
loop {
    let current_size = fs::metadata(log_file)?.len();
    if current_size > last_offset {
        let mut file = fs::File::open(log_file)?;
        file.seek(SeekFrom::Start(last_offset))?;
        let mut buf = String::new();
        file.read_to_string(&mut buf)?;
        for line in buf.lines() {
            println!("{line}");
        }
        last_offset = current_size;
    }
}
```

