pub async fn execute(args: LogsArgs) -> Result<()> {
    // Expand tilde in paths
    let work_dir = expand_tilde(&args.work_dir);
    let log_dir = expand_tilde(&args.log_dir);

    // Check if cluster is running
    if !state_exists(&work_dir) {
