    if !log_file.exists() {
        output::error(&format!("Log file not found: {}", log_file.display()));
        output::info(&format!(
            "The component '{}' may not have started successfully.",
            args.component
        ));
        return Err(anyhow::anyhow!("Log file not found"));
    }

