        let input = PathBuf::from("/absolute/path");
        let result = expand_tilde(&input);
        assert_eq!(result, input);
    }

    #[test]
    fn test_relative_path_no_tilde() {
        let input = PathBuf::from("relative/path");
        let result = expand_tilde(&input);
        assert_eq!(result, input);
    }
}

